=== FILE: rr_arbiter_formal.sv ===
// Formal property wrapper for rr_arbiter, derived from interface_spec.md.
// Immediate assertions in clocked blocks only (open Yosys front end subset).
module rr_arbiter_formal (
    input wire       clk,
    input wire       rst_n,
    input wire [2:0] req
);
    wire [2:0] grant;
    wire [1:0] last;

    rr_arbiter dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant),
        .last  (last)
    );

    // First-cycle flag guarding $past.
    reg f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    // Environment: the block starts in reset (spec defines behaviour from reset).
    always @(*)
        if (!f_past_valid)
            assume(!rst_n);

    // Spec reference model of the priority order: last+1, last+2, last (mod 3).
    wire [1:0] f_p1 = (last == 2'd2) ? 2'd0 : (last + 2'd1);
    wire [1:0] f_p2 = (f_p1 == 2'd2) ? 2'd0 : (f_p1 + 2'd1);
    wire [1:0] f_p3 = last;
    wire [2:0] f_exp = req[f_p1] ? (3'b001 << f_p1) :
                       req[f_p2] ? (3'b001 << f_p2) :
                       req[f_p3] ? (3'b001 << f_p3) : 3'b000;

    // Wait counters for RR-BOUND: edges at which requester i asked and was not granted.
    reg [1:0] f_wait0 = 2'd0;
    reg [1:0] f_wait1 = 2'd0;
    reg [1:0] f_wait2 = 2'd0;
    always @(posedge clk) begin
        if (!rst_n)
            f_wait0 <= 2'd0;
        else if (req[0] && !grant[0])
            f_wait0 <= (f_wait0 == 2'd3) ? 2'd3 : (f_wait0 + 2'd1);
        else
            f_wait0 <= 2'd0;
    end
    always @(posedge clk) begin
        if (!rst_n)
            f_wait1 <= 2'd0;
        else if (req[1] && !grant[1])
            f_wait1 <= (f_wait1 == 2'd3) ? 2'd3 : (f_wait1 + 2'd1);
        else
            f_wait1 <= 2'd0;
    end
    always @(posedge clk) begin
        if (!rst_n)
            f_wait2 <= 2'd0;
        else if (req[2] && !grant[2])
            f_wait2 <= (f_wait2 == 2'd3) ? 2'd3 : (f_wait2 + 2'd1);
        else
            f_wait2 <= 2'd0;
    end

    always @(posedge clk) begin
        // Helper invariant: last is 0, 1 or 2 (spec section 1).
        if (f_past_valid)
            assert(last != 2'd3);

        // RR-RESET: reset loads last = 2.
        if (f_past_valid && !$past(rst_n))
            assert(last == 2'd2);

        // RR-IDLE: no request, no grant.
        if (f_past_valid && req == 3'b000)
            assert(grant == 3'b000);

        // RR-PICK (one-hot part): some request means exactly one grant.
        if (f_past_valid && req != 3'b000)
            assert(grant == 3'b001 || grant == 3'b010 || grant == 3'b100);

        // RR-PICK: the grant is the first requester in the rotation order.
        if (f_past_valid)
            assert(grant == f_exp);

        // RR-ONLY-REQUESTERS: never grant a non-requester.
        if (f_past_valid)
            assert((grant & ~req) == 3'b000);

        // RR-ROTATE: a grant moves last to the granted requester.
        if (f_past_valid && $past(rst_n) && $past(grant) != 3'b000)
            assert((3'b001 << last) == $past(grant));

        // RR-HOLD: no grant, last unchanged.
        if (f_past_valid && $past(rst_n) && $past(grant) == 3'b000)
            assert(last == $past(last));

        // RR-YIELD: last cycle's grantee yields to any other requester.
        if (f_past_valid && $past(rst_n) && $past(grant) != 3'b000 && (req & ~$past(grant)) != 3'b000)
            assert((grant & $past(grant)) == 3'b000);

        // RR-BOUND: helper bounds on the wait counters.
        if (f_past_valid)
            assert(f_wait0 <= 2'd2);
        if (f_past_valid)
            assert(f_wait1 <= 2'd2);
        if (f_past_valid)
            assert(f_wait2 <= 2'd2);

        // RR-BOUND: after two lost edges, the third edge grants.
        if (f_past_valid && req[0] && f_wait0 == 2'd2)
            assert(grant[0]);
        if (f_past_valid && req[1] && f_wait1 == 2'd2)
            assert(grant[1]);
        if (f_past_valid && req[2] && f_wait2 == 2'd2)
            assert(grant[2]);
    end

    // Covers: scenarios the proof must still allow.
    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover(req == 3'b111);
            cover(grant == 3'b001);
            cover(grant == 3'b010);
            cover(grant == 3'b100);
            cover(req[0] && f_wait0 == 2'd2);
            cover(req[1] && f_wait1 == 2'd2);
            cover(req[2] && f_wait2 == 2'd2);
        end
        if (f_past_valid && $past(rst_n)) begin
            cover($past(grant) == 3'b100 && grant == 3'b001);
            cover($past(grant) == 3'b000 && last != 2'd2);
            cover($past(grant) != 3'b000 && (req & ~$past(grant)) != 3'b000);
        end
        if (f_past_valid && $past(f_past_valid) && $past(rst_n))
            cover(!rst_n && last != 2'd2);
    end
endmodule
=== END FILE ===
